// v2.14.3 P.1-P.3: extended platform-override system. The Android APK
// build now needs a dedicated archive — Capacitor / WebView / scoped
// storage / cloud embeddings / AlarmManager-driven proactive flow are
// all materially different from the PC Electron + ONNX bge-m3 +
// notification-tray flow that SOFTWARE_GUIDE_SECTIONS describes.
//
// HARD CONSTRAINT: the PC content must stay byte-identical. We do NOT
// touch SOFTWARE_GUIDE_SECTIONS at all. Instead we publish a
// per-section override dictionary; getSoftwareGuideSections() swaps
// matching ids when called with platform='mobile' and otherwise returns
// the base array untouched.
//
// Every override re-uses the same id (so deep links / activeGuideSection
// state continues to resolve), inherits the same `icon`, but ships its
// own `title` + Android-rewritten `content`. Sections with no override
// (memory / diary / world / profile) fall through to the PC text — they
// are platform-agnostic and rewriting them would create busywork without
// surfacing any Android-specific information.
interface AndroidGuideOverride {
    title: string;
    content: string;
}

// Note: keep keys grouped by chapter id to make it easy to scan diffs
// against SOFTWARE_GUIDE_SECTIONS when re-reading the PC text.
