/**
 * v2.14.3 P.1-P.3: platform-aware accessor over SOFTWARE_GUIDE_SECTIONS.
 *
 * - 'desktop' (PC / Electron) returns the chapter list verbatim — PC
 *   content is a hard constraint of v2.14.3 and must NEVER be mutated
 *   by Android-side changes.
 * - 'mobile' (Capacitor / Android APK) walks the base chapter list and,
 *   for any id that has an entry in ANDROID_GUIDE_OVERRIDES[language],
 *   replaces the title + content while keeping the original id and icon.
 *   Sections without an override (memory / diary / world / profile) are
 *   passed through untouched: their PC text is platform-agnostic and
 *   would only be lossy to rewrite.
 *
 * Ids stay stable so deep links, the `activeGuideSection` Zustand state,
 * and the FullGuideModal mobile tab strip all continue to resolve.
 */
export function getSoftwareGuideSections(
    language: 'zh' | 'en',
    platform: GuidePlatform = 'desktop',
): typeof SOFTWARE_GUIDE_SECTIONS['zh'] {
    const base = SOFTWARE_GUIDE_SECTIONS[language];
    if (platform !== 'mobile') return base;
    const overrides = ANDROID_GUIDE_OVERRIDES[language] ?? {};
    return base.map((section) => {
        const override = overrides[section.id];
        if (!override) return section;
        return { ...section, title: override.title, content: override.content };
    }) as typeof SOFTWARE_GUIDE_SECTIONS['zh'];
}
